<?php
$u=sr_auth('admin');$q=trim((string)($_GET['q']??''));$term='%'.$q.'%';
$users=sr_all('SELECT u.*,COALESCE(f.is_active,1) AS is_active FROM users u LEFT JOIN user_flags f ON f.user_id=u.id WHERE u.name LIKE ? OR u.email LIKE ? ORDER BY u.id DESC LIMIT 300',[$term,$term]);
sr_page_heading('QUẢN TRỊ HỆ THỐNG','Quản lý tài khoản','Tra cứu tài khoản ứng viên và doanh nghiệp, xử lý tài khoản không hợp lệ.');
?><div class="toolbar"><form method="get" class="inline-filter"><input type="hidden" name="page" value="admin_users"><input type="search" name="q" placeholder="Tìm theo tên hoặc email..." value="<?=h($q)?>"><button class="button primary sm">Tìm kiếm</button></form><span class="muted"><?=count($users)?> kết quả</span></div><div class="panel table-panel"><div class="table-responsive"><table><thead><tr><th>Người dùng</th><th>Vai trò</th><th>Ngày tham gia</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><?php foreach($users as $account):?><tr><td><strong><?=h($account['name'])?></strong><small><?=h($account['email'])?></small></td><td><?=h($account['role'])?></td><td><?=h(sr_date($account['created_at']))?></td><td><span class="badge <?=((int)$account['is_active']===1?'success':'danger')?>"><?=((int)$account['is_active']===1?'Hoạt động':'Đã khóa')?></span></td><td><?php if($account['role']!=='admin'):?><form method="post" data-confirm="Bạn chắc chắn muốn thay đổi trạng thái tài khoản này?"><?=sr_token()?><input type="hidden" name="action" value="user_toggle"><input type="hidden" name="id" value="<?=$account['id']?>"><input type="hidden" name="active" value="<?=((int)$account['is_active']===1)?0:1?>"><button class="button <?=((int)$account['is_active']===1)?'danger-outline':'secondary'?> xs"><?=((int)$account['is_active']===1)?'Khóa':'Mở khóa'?></button></form><?php else:?><span class="muted">—</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div>
